\label{main thm}
    Let $k\geq 2$, and let $M_k$, $P_k$ and $Y=\{0,2,3,\hdots, M_k\}$ be as in \eqref{e;MkPk}; these depend only on $k$. There is $K = k^{O(k)}$ such that for every prime $p\geq P_k$ there exist $C= C(k,p)>0$ and $c=c(k,p)>0$ with the following property. If $n > \exp^{(K)}(1)$ and $A \subseteq \mathbb{F}_p^n$ satisfies
    \begin{align*}
        \frac{|A|}{p^n}  \geq \frac{C}{\left( \log^{(K)} n \right)^c},
    \end{align*}
    then $A$ contains a nontrivial restricted $k$-term polynomial progression $x, x+P_1(y),\ldots,x+P_{k-1}(y)$ with $y \in Y^n\setminus\{\vec 0\}$. Moreover, the $k$ points of any such progression are pairwise distinct.

\label{r;conditions}
    We record where each condition in \eqref{e;MkPk} is used.
    \begin{enumerate}
        \item[(a)] $M_k = M(k-1)\geq k$ (see the discussion before Lemma \ref{lem:finitelyManyRowsSuffice}) and $p>P(k-1)$. Together with $p>M_k$ below, these are the hypotheses of Proposition \ref{prop:noAbelianEmbeddings}, applied with $\ell = k-1$. The condition $M_k \geq k$ is used in the equal-characteristic case (Lemma \ref{lem:sameChar}), and $p>P(k-1)$ in the case of different characteristic (Lemma \ref{lem:diffChar}).
        \item[(b)] $p>M_k$, which follows from $p > M_k^{k-1}$. The elements of $Y$ are then distinct modulo $p$. Hence the tuples $(x,x+y,\ldots,x+y^{k-1})$, $x\in\mathbb{F}_p$, $y\in Y$, are pairwise distinct, as used in the computation of the atoms and marginals of $\mu$ in Lemma \ref{l;large exp}. The same condition makes the Vandermonde determinant in Lemma \ref{lem:sameChar} nonzero in $\mathbb{F}_p$.
        \item[(c)] $p>M_k^{k-1}$. For $y\in\{2,\ldots,M_k\}$ we have $1<y<y^2<\cdots<y^{k-1}<p$, so $0, y, y^2,\ldots,y^{k-1}$ are distinct in $\mathbb{F}_p$. If $y\in Y^n\setminus\{\vec 0\}$, some coordinate has $y_i\in\{2,\ldots,M_k\}$. Comparing the points $x, x+P_1(y),\ldots,x+P_{k-1}(y)$ in that coordinate shows that they are pairwise distinct. Without this condition a ``nontrivial'' progression could collapse to fewer than $k$ points.
    \end{enumerate}

\label{d;abelianEmbedding}
    Let $\Sigma_1,\ldots , \Sigma_k$ be finite alphabets and $\mathcal{S}\subseteq \prod_{i=1}^k \Sigma_i$. For an abelian group $(G,+)$, we say that maps $\sigma_i:\Sigma_i\rightarrow G$, $i=1,\ldots,k$, form an \textit{abelian embedding} of $\mathcal{S}$ if \begin{align*}
        (a_1,\ldots,a_k)\in \mathcal{S}\implies \sum_{i=1}^k\sigma_i(a_i)=0_G.
    \end{align*} The embedding is \textit{trivial} if every $\sigma_i$ is constant, and \textit{nontrivial} otherwise. A distribution $\mu$ over $\prod_{i=1}^k\Sigma_i$ \textit{admits a nontrivial abelian embedding} if its support $\operatorname{supp}\mu$ has a nontrivial abelian embedding into some abelian group, and \textit{admits no nontrivial abelian embedding} otherwise.

\cite[Theorem 1]{CSP_7}
\label{t;inverse}
Let \( k \) be a positive integer and let \( \mu \)  be a distribution over
\( \Sigma_1 \times \cdots \times \Sigma_k \) that admits no nontrivial abelian embedding, and in which the probability of each atom is at least \( \gamma \).
 Then, for every \( \epsilon>0 \)   there are \( \delta\coloneqq \delta(\gamma,\epsilon) >0 \) and \( N_0 = N_0(\gamma,\epsilon) \)
  such that for every \( n\geq N_0 \), if 1-bounded
functions \( f_i \colon \Sigma_{i}^n \to \mathbb{C} \)  satisfy
\begin{equation}
    \left| \operatorname*{\scalerel*{\mathbb{E}}{\textstyle\sum}}_{(x_1, \  \ldots, \  x_k) \sim \mu^{\otimes n}}
    \prod_{i=1}^k f_i(x_i) \right| \geq \epsilon,
\end{equation}
then \(\textup{Stab}_{1-\delta} (f_i) > \delta\) for all \( i=1, \ldots,k \), where the stability of \( f_i \) is taken with respect to the marginal \( \mu_i \) of \( \mu \) on \( \Sigma_i \).
 Quantitatively, we can take $k^{O(k)}$ iterates of the exponential function; that is,
\begin{equation}
    \delta \coloneqq \exp(- \exp^{(k^{O(k)})}(\epsilon^{-O_\gamma(1)}) ).
\end{equation}

Let $0\leq \rho <1$. The \textit{$\rho$-stability} of $f \in L^2( \Sigma^n, \pi^{\otimes n}) $ is given by
    \begin{equation}
    \operatorname{Stab}_\rho(f) \coloneqq \langle f, N_ \rho f \rangle_{L^2(\pi^{\otimes n})}.
\end{equation}
    When $f$ is defined on $\Sigma_j^n$ for one of the alphabets of a joint distribution $\mu$, stability is always taken with respect to the marginal $\pi = \mu_j$ of $\mu$ on the $j$-th coordinate. This is the convention in Theorem \ref{t;inverse}.

Let $\Sigma$ be a finite set, $n \geq 1$, and let $\pi$ be a probability distribution on $\Sigma$. A function $f: \Sigma^n  \rightarrow \mathbb{C}$ is \textit{homogeneous of degree $d$} if $f = \sum_{S; |S| = d} f^{=S}$. In addition, the \textit{weight of $f$ at degree at most $d$} is defined by
\begin{equation}
    W_{\leq d} (f) \coloneqq \sum_{\lvert S\rvert\leq d} \lVert f^{=S} \rVert_2^2.
\end{equation}

Let $(G,+)$ be an abelian group and suppose the maps $f_i:\Sigma_i \rightarrow G$, $0 \leq i \leq \ell$, form a nontrivial abelian embedding of $\mu$ into $G$. The sets $\Sigma_i$ are finite, so the maps $f_0,\ldots,f_\ell$ have finite images. Replacing $G$ by the subgroup generated by these images, we may assume that $G$ is finitely generated. Then there exist nonnegative integers $r, n_1,\ldots,n_s$ and primes $q_1,\ldots,q_s$ such that $G \cong \mathbb{Z}^r \oplus \mathbb{Z}/q_1^{n_1} \mathbb{Z} \oplus \cdots \oplus  \mathbb{Z}/q_s^{n_s}\mathbb{Z}$. Composing $f_0,\ldots,f_\ell$ with the projection onto any cyclic summand gives an abelian embedding into that summand, since projections are homomorphisms. At least one of these embeddings is nontrivial: if all were trivial, each $f_i$ would be constant in every coordinate, hence constant. There are two cases.

    \emph{Case 1: a nontrivial embedding $f_0',\ldots,f_\ell'$ into $\mathbb{Z}$.} Some $f_i'$ takes two distinct values. Let $q$ be a prime larger than $|f_i'(a) - f_i'(b)|$ for all $0 \leq i \leq \ell$ and $a, b \in \Sigma_i$. Let $\pi:\mathbb{Z} \rightarrow \mathbb{Z}/q\mathbb{Z}$ be reduction mod $q$. Then $\pi \circ f_0',\ldots,\pi \circ f_\ell'$ is an abelian embedding into $\mathbb{Z}/q\mathbb{Z}$, and it is nontrivial because $\pi$ is injective on the finite set of values of each $f_i'$.

    \emph{Case 2: a nontrivial embedding into $\mathbb{Z}/q^n \mathbb{Z}$ for some prime $q$ and $n\geq 1$.} We show by induction on $n$ that there is then a nontrivial embedding into $\mathbb{Z}/q\mathbb{Z}$. The case $n=1$ is immediate. Suppose the claim holds for some $n\geq 1$, and let $f_0,\ldots,f_\ell$ be a nontrivial embedding into $\mathbb{Z}/q^{n+1}\mathbb{Z}$. We identify $\mathbb{Z}/q^{n+1}\mathbb{Z}$ with the residues $\{0,1,\ldots,q^{n+1}-1\}$. The maps $g_j \coloneqq f_j \bmod q^n$ form an embedding into $\mathbb{Z}/q^n\mathbb{Z}$, since reduction mod $q^n$ is a homomorphism. If this embedding is nontrivial, the induction hypothesis finishes the proof.

    Otherwise, every $g_j$ is constant, say $g_j \equiv c_j$ with $c_j \in \{0,1,\ldots,q^n-1\}$. Then, write each \( f_j \) as 
    \begin{align*}
        f_j(x) = c_j + q^n\phi_j(x), \qquad \phi_j:\Sigma_j \to \{0,1,\ldots,q-1\},
    \end{align*}
    and since the $f_j$ are not all constant, the $\phi_j$ are not all constant. Pick any $(x_0,\ldots,x_\ell) \in \operatorname{supp}\mu$. Reducing $\sum_j f_j(x_j) \equiv 0 \pmod{q^{n+1}}$ modulo $q^n$ gives $\sum_j c_j \equiv 0 \pmod{q^n}$. Write $\sum_j c_j = q^n c$ with $c \in \mathbb{Z}$. Then for every $(x_0,\ldots,x_\ell)\in\operatorname{supp}\mu$,
    \begin{align*}
        0 \equiv \sum_{j=0}^\ell f_j(x_j) = q^n\Big(c + \sum_{j=0}^\ell \phi_j(x_j)\Big) \pmod{q^{n+1}},
    \end{align*}
    so $c + \sum_{j} \phi_j(x_j) \equiv 0 \pmod q$. Hence the maps $\phi_0 + c,\ \phi_1,\ldots,\phi_\ell$, reduced mod $q$, form an abelian embedding into $\mathbb{Z}/q\mathbb{Z}$. It is nontrivial because each $\phi_j$ takes values in $\{0,\ldots,q-1\}$, where reduction mod $q$ is injective, and some $\phi_j$ is nonconstant.

\label{prop:noAbelianEmbeddings}
    Let $\ell\geq 1$, and let $M(\ell)$ and $P(\ell)$ be as in Proposition \ref{prop:uniformTorsionRank}. Let $M \geq \max\{M(\ell), \ell+1\}$ be an integer and let $p > \max\{M, P(\ell)\}$ be prime. Let $\mu$ be a probability distribution on $\mathbb{F}_p^{\ell+1}$ whose support is exactly the set 
    \begin{align*}
        \Big\{(x,x+y,x+y^2,\hdots,x+y^\ell) : \ x\in \mathbb{F}_p,\ y\in \{0,2,\ldots, M\}\Big\}.
    \end{align*}
    Then $\mu$ admits no nontrivial abelian embedding.

\label{lem:sameChar}
    Let $\ell \geq 1$, let $M\geq \ell+1$, and let $p > M$ be prime. If $f_0,\hdots,f_\ell:\mathbb{F}_p\rightarrow \mathbb{F}_p$ satisfy
    \begin{align}\label{eq:sameCharSystem}
        f_0 (x) + \sum_{j=1}^{\ell}f_j(x+y^j)=0 \qquad \text{for all } x \in \mathbb{F}_p \text{ and } y\in \{0,2,\hdots,M\},
    \end{align}
    then $f_j$ is constant for every $j = 0,1, \ldots, \ell$. That is, $\mu$ admits no nontrivial abelian embedding into $(\mathbb{F}_p,+)$.

Evaluating \eqref{eq:sameCharSystem} at $y=0$ gives
    \begin{align}\label{eq:yZero}
        f_0(x)+f_1(x)+\hdots+f_\ell(x)=0, \qquad x \in \mathbb{F}_p.
    \end{align}
    Subtracting \eqref{eq:yZero} from \eqref{eq:sameCharSystem} eliminates $f_0$:
    \begin{align}\label{eq:sameCharDiff}
        \sum_{j=1}^\ell (T^{y^j}-\text{Id})f_j=0, \qquad y\in \{2,\hdots,M\},
    \end{align}
    where $T$ is the translation operator $Tf(x) \coloneqq f(x+1)$ on functions $\mathbb{F}_p \to \mathbb{F}_p$.

    \emph{The ring $R$.} Since $T^p = \text{Id}$, the space of functions $\mathbb{F}_p \to \mathbb{F}_p$ is a module over $R\coloneqq\mathbb{F}_p[T]/(T^p-1)$. In characteristic $p$ we have $T^p-1=(T-1)^p$, so $T - 1$ is nilpotent in $R$. Consequently, an element $F(T) \in R$ is a unit if and only if $F(1)\neq 0$. Indeed, write $F(T) = F(1) + (T-1)G(T)$. If $F(1) \neq 0$, then $F(T) = F(1)\big(1 + N\big)$ with $N = F(1)^{-1}(T-1)G(T)$ nilpotent, and $1+N$ has inverse $\sum_{i=0}^{p-1}(-N)^i$. If $F(1) = 0$, then $F(T)$ is a multiple of the nilpotent element $T-1$, hence not a unit.

    \emph{Factoring out $T - 1$.} For $y\geq 2$ and $1\leq j\leq \ell$,
    \begin{align*}
        T^{y^j}-1 = (T-1)B_{y,j}(T), \qquad B_{y,j}(T) \coloneqq 1+T+\cdots + T^{y^j-1}, \qquad B_{y,j}(1) = y^j.
    \end{align*}
    Setting $g_j \coloneqq (T-\text{Id})f_j$, and using that polynomials in $T$ commute, \eqref{eq:sameCharDiff} becomes $\sum_{j=1}^\ell B_{y,j}(T)\,g_j = 0$ for $y\in\{2,\ldots,M\}$. Keep only the $\ell$ rows $y_r \coloneqq r+1$, $1 \leq r \leq \ell$. These lie in $\{2,\ldots,M\}$ because $M\geq \ell+1$. Let $B(T)\coloneqq \big(B_{y_r,j}(T)\big)_{1\leq r,j\leq \ell}$, a $\ell\times \ell$ matrix over $R$. Then
    \begin{align*}
        B(T)\,\vec g = 0, \qquad \vec g \coloneqq (g_1,\ldots,g_\ell)^{\top}.
    \end{align*}

    \emph{Invertibility.} The determinant commutes with the ring homomorphism $R \to \mathbb{F}_p$, $T \mapsto 1$, so $\det B(T)$ evaluated at $T=1$ equals the Vandermonde-type determinant
    \begin{align*}
        \det\big(y_r^j\big)_{1\leq r,j\leq \ell}=\prod_{r=1}^\ell y_r\cdot \prod_{1\leq r<s\leq \ell}(y_s-y_r).
    \end{align*}
    Every factor is an integer in $\{1,\ldots,M\}$, hence nonzero in $\mathbb{F}_p$ because $p>M$. Thus $\det B(T)$ is a unit in $R$. Multiplying $B(T)\vec g = 0$ by the adjugate of $B(T)$ gives $\det B(T)\, g_j = 0$, and therefore $g_j = 0$ for each $j$.

    \emph{Conclusion.} For $1 \leq j \leq \ell$, $g_j = 0$ means $f_j(x+1)=f_j(x)$ for all $x\in\mathbb{F}_p$, so $f_j$ is constant. By \eqref{eq:yZero}, $f_0=-(f_1+\cdots+f_\ell)$ is constant as well.

\label{prop:uniformTorsionRank}
    For integers $\ell\geq 1$ and $M\geq 2$ define the $(M-1)\times \ell$ matrix \begin{align*}
        A_{\ell,M}(z)\coloneqq(z^{y^j}-1)_{\substack{2\leq y\leq M\\ 1\leq j\leq \ell}}.
    \end{align*} Then, there exists some $M=M(\ell)$ and $P=P(\ell)$ with the following property. If $p>P$ and $q\neq p$ are primes, and $\lambda \in \overline{\mathbb{F}}_q^\times$ has multiplicative order $p$, then $A_{\ell,M}(\lambda)$ has rank $\ell$.

Suppose that $A_{\ell,\infty}(\theta)$ has rank $r<\ell$ at some nonzero algebraic number $\theta$. Then, there exist algebraic numbers $c_1,\hdots,c_\ell$, not all zero, such that \begin{align*}
        \sum_{j=1}^l c_j(\theta^{y^j}-1)=0,\quad \forall y\geq 2.
    \end{align*} Let $C \coloneqq c_1+\hdots + c_\ell$, then $\sum_{j=1}^\ell c_j \theta^{y^j}=C$ for all $y\geq 2$. We will show that this forces $\theta$ to be a root of unity.

    Suppose by way of contradiction that $\theta$ is not a root of unity. Let $K$ be a number field containing $\theta$ and $c_1,\ldots,c_\ell$. By Lemma \ref{lem:kronecker}, there exists a place $v$ of $K$ such that $|\theta|_v\neq 1$; all absolute values below are taken with this place. We will use this to force a contradiction (and won't need any deeper structure about the place $v$).

    Consider first where $|\theta|_v>1$. Among the indices $j$ such that $c_j$ is nonzero, let $j_+$ be the largest. Dividing our constraint equation by $c_{j_+}\theta^{y^{j_+}}$, one obtains that \begin{align*}
        1+\sum_{1\leq j<j_+}\frac{c_j}{c_{j_+}}\theta^{y^j-y^{j_+}}=\frac{C}{c_{j_+}\theta^{y^{j_+}}}.
    \end{align*} By the triangle inequality for $|\cdot |_v$, then, \begin{align*}
        1\leq \Big|\frac{C}{c_{j_+}}\Big|_v|\theta|_v^{-y^{j_+}}+\sum_{1\leq j<j_+}\Big|\frac{c_j}{c_{j_+}}\Big|_v|\theta|_v^{y^j-y^{j_+}}.
    \end{align*} Since $|\theta|_v>1$ and maximality of $j_+$, by taking $y\rightarrow \infty$ we obtain a contradiction.

    Now consider where $|\theta|_v<1$. Considering the equation $\sum_{j=1}^\ell c_j\theta^{y^j}=C$ and taking $y\rightarrow \infty$, one observes that $C=0$. Thus, $\sum_{j=1}^\ell c_j\theta^{y^j}=0$. Now, among the indices $j$ such that $c_j$ is nonzero, let $j_-$ be the smallest. A similar argument as in the first case then gives a contradiction (dividing in this case by the lowest contributory monomial).

\label{lem:minorsMonic}
    Let $2\leq y_1<y_2<\cdots<y_\ell$ be integers. Then the minor
    \begin{align*}
        \Delta(z) \coloneqq \det\big(z^{y_r^j}-1\big)_{1\leq r,j\leq \ell}\in \mathbb{Z}[z]
    \end{align*}
    is monic of degree $\sum_{r=1}^\ell y_r^{r}$. In particular, for every prime $q$ its reduction $\overline{\Delta}\in \mathbb{F}_q[z]$ is a nonzero polynomial of the same degree.

Expanding the determinant,
    \begin{align*}
        \Delta(z) = \sum_{\sigma\in \textup{Sym}_\ell}\operatorname{sgn}(\sigma)\prod_{r=1}^\ell\big(z^{y_r^{\sigma(r)}}-1\big).
    \end{align*}
    The term indexed by $\sigma$ is a polynomial of degree $e(\sigma)\coloneqq\sum_{r=1}^\ell y_r^{\sigma(r)}$ with leading coefficient $\operatorname{sgn}(\sigma)$. We claim that $e(\sigma)<e(\mathrm{id})$ for every $\sigma\neq \mathrm{id}$. Then the monomial $z^{e(\mathrm{id})}$ occurs only in the term $\sigma = \mathrm{id}$, with coefficient $+1$, which proves the lemma.

    We prove the claim by induction on the number of inversions of $\sigma$. If $\sigma\neq\mathrm{id}$, there are $r<s$ with $a\coloneqq\sigma(s)<b\coloneqq\sigma(r)$. Let $\tau$ agree with $\sigma$ except that $\tau(r)=a$ and $\tau(s)=b$. Then $\tau$ has fewer inversions than $\sigma$, and 
    \begin{align*}
        e(\tau)-e(\sigma) = \big(y_s^{b}-y_s^{a}\big)-\big(y_r^{b}-y_r^{a}\big) = \phi(y_s)-\phi(y_r), \qquad \phi(t)\coloneqq t^{a}\big(t^{b-a}-1\big).
    \end{align*}
    The function $\phi$ is strictly increasing on $[1,\infty)$, and $y_s>y_r\geq 2$, so $e(\tau)>e(\sigma)$. By induction $e(\tau) \leq e(\mathrm{id})$, and hence $e(\sigma)<e(\mathrm{id})$.

Fix a prime $q\mid N$, and let $G_q(z)$ be the greatest common divisor in $\mathbb{F}_q[z]$ of the reductions $\overline{\Delta(M_{S_1})},\hdots,\overline{\Delta(M_{S_t})}$. By Lemma \ref{lem:minorsMonic}, each of these reductions is a nonzero polynomial. Hence $G_q\neq 0$, and 
    \begin{align*}
        d_q\coloneqq\deg G_q\leq \deg \overline{\Delta(M_{S_1})} = \deg \Delta(M_{S_1}).
    \end{align*}
    (Without this, $G_q$ could be the zero polynomial, every $\lambda$ would be a common root, and the argument would give no information.) Every common root $\lambda$ is a root of $G_q$, and the roots of the nonzero polynomial $G_q$ lie in extensions of $\mathbb{F}_q$ of degree at most $d_q$: that is, $\lambda\in \mathbb{F}_{q^r}$ for some $1\leq r\leq d_q$. If $\lambda\neq 0$, then $\lambda^{q^r-1}=1$. Set
    \begin{align*}
        c_\ell\coloneqq \operatorname{lcm}\big\{q^r-1:\ q \text{ prime},\ q\mid N,\ 1\leq r\leq d_q\big\}.
    \end{align*}
    This is a finite least common multiple, since $N$ has finitely many prime divisors, and it depends only on $\ell$, since $N$, the sets $S_1,\ldots,S_t$ and hence each $d_q$ depend only on $\ell$. Every $\lambda$ as in the statement satisfies $\lambda^{c_\ell}=1$.

Choose $M=M(\ell)$ as defined before Lemma \ref{lem:finitelyManyRowsSuffice}, and choose 
    \begin{align*}
        P > \max\Big(\mathcal{E}_\ell \cup \{c_\ell\}\Big),
    \end{align*}
    with $c_\ell$ as in Lemma \ref{lem:exceptionalCharacteristics}. Both quantities depend only on $\ell$. Let $p>P$ and $q\neq p$ be primes, and let $\lambda\in\overline{\mathbb{F}}_q^\times$ have multiplicative order $p$. Suppose, for contradiction, that $A_{\ell,M}(\lambda)$ has rank less than $\ell$. Then every $\ell\times \ell$ minor of $A_{\ell,M}(\lambda)$ vanishes. The generating sets $S_1,\ldots,S_t$ lie in $\{2,\ldots,M(\ell)\}$, and the entries $z^{y^j}-1$ have integer coefficients, so evaluating the reduction $\overline{\Delta(M_{S_i})}$ at $\lambda$ gives a $\ell \times \ell$ minor of $A_{\ell,M}(\lambda)$. Hence $\lambda$ is a common root of $\overline{\Delta(M_{S_1})},\ldots,\overline{\Delta(M_{S_t})}$.

    If $q\nmid N$, the discussion above gives $\overline{D}(\lambda)=0$, and Lemma \ref{lem:goodCharacteristics} gives $\lambda^m=1$ for some $m\in\mathcal{E}_\ell$. Since $\lambda$ has order $p$, this forces $p\mid m$, so $p\leq m<P$, a contradiction. If $q\mid N$, Lemma \ref{lem:exceptionalCharacteristics} gives $\lambda^{c_\ell}=1$, so $p\mid c_\ell$ and $p\leq c_\ell<P$, again a contradiction. Hence $A_{\ell,M}(\lambda)$ has rank $\ell$.

To prove the contrapositive, assume 
    \begin{align*}
         W_{\leq d} [f - \mathbb{E} f]  & = \sum_{\substack{\# \xi \leq d \\ \xi \neq 0}} |\widehat{f}(\xi)|^2 < \frac{\delta}{2}. 
     \end{align*}
     To show that the balanced function is stable enough, consider
     \begin{align*}
         \operatorname{Stab}_{1- \delta} [f - \mathbb{E} f]  & = \sum_{\xi \in \{0,\ldots,|\Sigma|-1\}^n} (1- \delta)^{\# \xi} (f- \mathbb{E} f)^{\wedge} (\xi)^2 \\
         &= \sum_{\xi \neq 0 } (1- \delta)^{\# \xi} |\widehat{f} (\xi)|^2 \\
         &\leq \sum_{\substack{\xi \neq 0; \\ \# \xi \leq d }} (1- \delta)^{\# \xi} |\widehat{f} (\xi)|^2  + (1- \delta)^{d+1 }\sum_{\substack{\xi \neq 0; \\ \# \xi > d }}  |\widehat{f} (\xi)|^2. 
     \end{align*}
     By assumption, the function $f- \mathbb{E} f$ is essentially of high degree. Hence, the right-hand side of the inequality above is 
     \begin{align*}
         &\leq \frac{\delta}{2} + (1- \delta)^{d+1 } \sum_{\substack{\xi \neq 0; \\ n \geq  \# \xi > d }}  |\widehat{f} (\xi)|^2 
     \end{align*}
    for $d= O(\delta^{-1} \log ( 2 \delta^{-1}))$. By Plancherel and since $1 - \delta \leq e^{-\delta}$, the right-hand side of the inequality above is 
    \begin{align*}
         & \leq \frac{\delta}{2} + e^{-\delta d} \mathbb{E} (f^2). 
     \end{align*}
     For $d \geq \delta^{-1} \log (2/\delta)$, and since $f$ is $1$-bounded, we conclude that 
     \begin{align*}
         \operatorname{Stab}_{1- \delta} [f - \mathbb{E} f] & \leq \frac{\delta}{2} + \frac{\delta}{2}  \leq \delta. 
     \end{align*}

\label{p;restriction}
    Let $\Sigma$ be a finite set with a probability measure $\pi$. Let $f: \Sigma^n \rightarrow \{0, 1\}$, let $d \geq 2$ be an integer, and let $\beta > 0$ be such that $W_{\leq d} [f- \mathbb{E} f] \geq \beta$ and
    \begin{align*}
        \beta \geq 16 \exp \left( - \frac{n}{2d^2} \right).
    \end{align*}
    Then there is $S \subseteq [n]$ of size $|S| \geq \frac{n}{2d}$ and $y \in \Sigma^{\overline{S}}$ such that
    \begin{align*}
        \operatorname*{\scalerel*{\mathbb{E}}{\textstyle\sum}}_{\pi^{\otimes S}} [f_{\overline{S} \rightarrow y}] \geq \operatorname*{\scalerel*{\mathbb{E}}{\textstyle\sum}} [f] + \frac{\beta}{16}.
    \end{align*}

Let $\alpha = \mathbb{E} [f]$. We choose a random restriction $(S, y)$ as follows: the set $S \subseteq [n]$ contains each $i \in [n]$ independently with probability $\frac{1}{d}$, and, given $S$, the point $y \sim \pi^{\otimes \overline{S}}$.

    \emph{The size of $S$.} The random variable $|S|$ is a sum of $n$ independent Bernoulli random variables with parameter $\frac{1}{d}$, so $\mathbb{E}|S| = \frac{n}{d}$. By Hoeffding's inequality,
    \begin{align}\label{e;hoeffding}
        \mathbb{P} \left( |S| < \frac{n}{2d} \right) \leq \mathbb{P} \left( |S| - \mathbb{E}|S| \leq -\frac{n}{2d} \right) \leq \exp \left( - \frac{2 (\frac{n}{2d})^2}{n} \right) = \exp \left( - \frac{n}{2d^2} \right).
    \end{align}

    \emph{The second moment.} Let $Z_{S, y} \coloneqq \mathbb{E}_{\pi^{\otimes S }} f_{\overline{S} \rightarrow y} = \mathbb{E}_{x_S \sim \pi^{\otimes S}} f (x_S, y)$. For fixed $S$, the function $y \mapsto Z_{S,y}$ is the conditional expectation of $f$ given the coordinates in $\overline{S}$, and its Efron--Stein decomposition is $\sum_{S' \subseteq \overline{S}} f^{=S'}$. By orthogonality,
    \begin{align*}
        \mathbb{E}_{y \sim \pi^{\otimes \overline{S}}} Z_{S,y}^2 = \sum_{S' \subseteq \overline{S}} \left\| f^{=S'} \right\|_{2}^2 .
    \end{align*}
    Averaging over $S$, and using $f^{=\emptyset} = \alpha$, we obtain
    \begin{align*}
        \mathbb{E} Z_{S,y}^2 = \sum_{S' \subseteq [n]} \mathbb{P}(S \cap S' = \emptyset) \left\| f^{=S'} \right\|_{2}^2
        \geq \alpha^2 + \sum_{0 < |S'| \leq d} \left( 1 - \frac{1}{d} \right)^{|S'|} \left\| f^{=S'} \right\|_{2}^2 .
    \end{align*}
    Since $(1 - \frac{1}{d})^{|S'|} \geq (1-\frac{1}{d})^{d} \geq \frac14$ for $|S'| \leq d$ and $d \geq 2$, and since $\sum_{0<|S'| \leq d} \left\| f^{=S'} \right\|_{2}^2 = W_{\leq d}[f - \mathbb{E} f] \geq \beta$, we conclude that
    \begin{align*}
        \mathbb{E} Z_{S,y}^2 \geq \alpha^2 + \frac{\beta}{4}.
    \end{align*}

    Since $Z_{S,y}^2$ is bounded below (it is non-negative) and bounded above by $1$, to obtain this lower bound $\alpha^2 + \frac{\beta}{4}$, a significant enough amount of probability is allocated to $\alpha^2 + \frac{\beta}{ 8}$. That is, 
    \begin{align*}
        \mathbb{P} \left( y, S; \hspace{.2in} Z^2_{S,y} \geq \alpha^2 + \frac{\beta}{8} \right) \geq \frac{\beta}{8}. 
    \end{align*}
    Indeed, consider the event $\mathcal{G} := \{S, y ; \ Z_{S,y}^2 \geq \alpha^2 + \frac{\beta}{8}\}$. We know that $0 \leq Z^2_{S,y} \leq 1$. Hence, 
    \begin{align*}
        \mathbb{E}[Z^2_{S,y}] &= \mathbb{E}[Z^2_{S,y} 1_{\mathcal{G}}] + \mathbb{E}[Z^2_{S,y} 1_{\mathcal{G}^c}] \\
        \mathbb{E}[Z^2_{S,y}]& \leq 1 \cdot \mathbb{P}(\mathcal{G}) + \left( \alpha^2 + \frac{\beta}{8} \right) \mathbb{P}(\mathcal{G}^c) 
    \end{align*}
    Using the lower bound computed earlier, we get
    \begin{align*}
        \alpha^2 + \frac{\beta}{4} & \leq  \mathbb{P}(\mathcal{G}) + \left( \alpha^2 + \frac{\beta}{8} \right) (1- \mathbb{P}(\mathcal{G})) \\
        \implies \frac{\beta}{8} & \leq \left( 1- \left(  \alpha^2 + \frac{\beta}{8} \right)\right) \mathbb{P}(\mathcal{G})
    \end{align*}
    where $\alpha^2 + \frac{\beta}{8} \leq 1$. We thus obtain 
    \begin{align*}
        \frac{\beta}{8} & \leq \mathbb{P}(\mathcal{G}) 
    \end{align*}
    as claimed. 
    By \eqref{e;hoeffding}, $|S| \geq \frac{n}{2d}$ with probability at least $1- \exp\left( - \frac{n}{2d^2} \right)$. Since $\mathbb{P}(E \cap F) \geq \mathbb{P}(E) + \mathbb{P}(F) - 1$ for any two events, the hypothesis $\exp\left( - \frac{n}{2d^2} \right) \leq \frac{\beta}{16}$ gives
    \begin{align*}
        \mathbb{P} \left( \mathcal{G} \cap \left\{ |S| \geq \frac{n}{2d} \right\} \right) \geq \frac{\beta}{8} - \exp\left( - \frac{n}{2d^2} \right) \geq \frac{\beta}{16} > 0 .
    \end{align*}
    We may therefore fix $(S,y)$ for which both events hold. Since $Z_{S,y} \geq 0$, on the event $\mathcal{G}$ we have $Z_{S,y} \geq \sqrt{\alpha^2 + \frac{\beta}{8}}$. Note that $\alpha^2 + \frac{\beta}{8} \leq \mathbb{E}[Z^2_{S,y}] \leq 1$. For $0 \leq \alpha \leq 1$ and $t \geq 0$ with $\alpha^2 + t \leq 1$,
    \begin{align*}
        \sqrt{\alpha^2 + t} - \alpha = \frac{t}{\sqrt{\alpha^2 + t} + \alpha} \geq \frac{t}{2},
    \end{align*}
    because both terms in the denominator are at most $1$. Taking $t = \frac{\beta}{8}$ gives
    \begin{align*}
        \operatorname*{\scalerel*{\mathbb{E}}{\textstyle\sum}}_{\pi^{\otimes S}} [f_{\overline{S} \rightarrow y}] = Z_{S,y} \geq \alpha + \frac{\beta}{16},
    \end{align*}
    with $|S| \geq \frac{n}{2d}$, which concludes the proof.

\label{l;large exp}
    Let $\mu$ be the distribution over $\mathbb{F}_p^k $ with mass $ \frac{1 }{2p} $ on $(a,\ldots, a)$ for every $a \in \mathbb{F}_p$, and $\frac{ 1}{2p (M_k -1)} $ on each element $\vec{a}$, where $\vec{a} \in \operatorname{supp} \mu \setminus \{(a,\ldots ,a) : a \in \mathbb{F}_p\}$. That is, $\mu = \frac{1}{2} \mu_{\operatorname{diag} } + \frac{1}{2} \mu_{\operatorname{off diag}}$, where $\mu_{\operatorname{diag} }$ and $\mu_{\operatorname{off diag} }$ are uniformly distributed conditional on being on the diagonal terms and on the off diagonal terms respectively. If $A$ has no valid $k$-tuple, then there are $1$-bounded functions $f_i: \mathbb{F}_p^n \to \mathbb{C}$, such that:
\begin{align} 
    &\max_{0 \leq j \leq k-1 }\left\{\left|\operatorname*{\scalerel*{\mathbb{E}}{\textstyle\sum}}_{(x_0, \ldots, x_{k-1}) \sim \mu^{\otimes n}}[f_A(x_j)\prod_{\substack{i\neq j \\ 0 \leq i \leq k-1}} f_i(x_i)]\right|; 0 \leq j \leq k -1 \right\}  \geq \frac{\alpha^k}{2^k-1}  - \frac{\alpha}{2^n (2^k -1)}. 
\end{align}
In addition, for each $0\leq j\leq k-1$ the marginal $\mu_j$ of $\mu$ on the $j$-th coordinate is the uniform measure on $\mathbb{F}_p$. In particular, $\mathbb{E}_{x \sim \mu_j^{\otimes n}}[A(x)] = \alpha$.

If $A$ has no valid $k$-tuple, then only the trivial $k$-tuples in the support of $\mu^{\otimes n}$ remain. Hence, the expectation
    \begin{equation}\label{eq exp A}
        \begin{split}
            \operatorname*{\scalerel*{\mathbb{E}}{\textstyle\sum}}_{x \sim \mu^{\otimes n}}  \prod_{j=0}^{k-1} A(x_j ) &= \sum_{(x_0, x_1, \ldots, x_{k-1}) \in \mathbb{F}^{kn}_p} A(x_0) \mu^{\otimes n} (x_0 = \cdots = x_{k-1})  = \sum_{x_0 \in \mathbb{F}_p^n} A(x_0) \frac{1}{(2p)^n} = \frac{\alpha}{2^n}. 
        \end{split}
    \end{equation}
    Letting $A = \alpha + f_A$, and distributing the resulting factors, we have
    \begin{align*}
        \operatorname*{\scalerel*{\mathbb{E}}{\textstyle\sum}}_{\mu^{\otimes n}}\prod_{j=0}^{k-1} A(x_j) & = \operatorname*{\scalerel*{\mathbb{E}}{\textstyle\sum}}_{\mu^{\otimes n}}\prod_{j=0}^{k-1} (\alpha + f_A)(x_j)  = \alpha^k + \sum_{l=1}^{2^k -1} \Theta_l,
    \end{align*}
    where $\Theta_l$ is the expectation of a product of $k$ functions with the balanced function $f_A$ appearing at least once. By the triangle inequality and \eqref{eq exp A}, 
    \begin{align*}
        \alpha^k &\leq \left|\operatorname*{\scalerel*{\mathbb{E}}{\textstyle\sum}}_{\mu^{\otimes n}}\prod_{j=0}^{k-1} A(x_j) \right|  + \sum_{l=1}^{2^k -1} |\Theta_l|  \leq \frac{\alpha}{2^n}  + \sum_{l=1}^{2^k -1} |\Theta_l|.
    \end{align*}
    By the pigeonhole principle, the desired estimate follows. 
    \begin{align*}
        \max_{1 \leq l \leq 2^k -1} |\Theta_l| \geq \frac{\alpha^k}{2^k -1} - \frac{\alpha}{2^n (2^{k} - 1) }. 
    \end{align*}
    Finally, we proceed and compute the marginal distribution for the distribution 
    \begin{align*}
        \mu(x_0, \ldots, x_{k-1}) &= \frac{1}{2 p} 1_{\textrm{diagonal}}(x_0, \ldots, x_{k-1}) + \frac{1 }{2 p (M_k -1)} 1_{\textrm{off diagonal}}(x_0, \ldots, x_{k-1}). 
    \end{align*}
    The marginal on the $0$-th coordinate, evaluated at a point $a$ in $\mathbb{F}_p$, is given by 
    \begin{align*}
        \mu_{0} (a)&= \sum_{\substack{(x_1, \ldots, x_{k-1}) \in \mathbb{F}^{k-1}_p \\ (x_0, \ldots, x_{k-1}) \in \operatorname{supp} \mu }} \frac{1}{2 p}  1_{\textrm{diagonal}} (a,x_1, \ldots, x_{k-1}) + \frac{1 }{2 p(M_k -1)}  1_{\textrm{off diagonal}}(a,x_1, \ldots, x_{k-1}) \\
        &= \frac{1}{2p}  + \frac{ 1 }{2 p (M_k -1)} (M_k -1) = \frac{1}{p} . 
    \end{align*}
    The same computation applies to the $j$-th coordinate for $1\leq j\leq k-1$. The diagonal tuple through $a$ contributes $\frac{1}{2p}$. For each $y\in\{2,\ldots,M_k\}$ there is exactly one off-diagonal tuple with $x_j=a$, namely the one with $x=a-y^j$, and these contribute $\frac{1}{2p}$ in total. Hence $\mu_j(a)=\frac1p$ for all $j$, and $\mathbb{E}_{x \sim \mu_j^{\otimes n}} A(x) = \alpha$.

\label{l;fiber}
    Let $A \subseteq \mathbb{F}_p^n$ contain no valid $k$-tuple. Then for every nonempty $S \subseteq [n]$ and every $u \in \mathbb{F}_p^{\overline{S}}$, the set
    \begin{align*}
        A_{\overline{S} \rightarrow u} \coloneqq \{ v \in \mathbb{F}_p^S : (x_S = v, \ x_{\overline{S}} = u) \in A \} \subseteq \mathbb{F}_p^S
    \end{align*}
    contains no valid $k$-tuple.

\label{l;increment}
    Let $0 < \alpha_0 \leq 1$, and let $\delta_0$, $d$ and $N(\alpha_0)$ be as in \eqref{e;de0} and \eqref{e;d0N}. Suppose that $A \subseteq \mathbb{F}_p^n$ contains no valid $k$-tuple, has density $\alpha = \frac{|A|}{p^n} \geq \alpha_0$, and that $n \geq N(\alpha_0)$. Then there exist $S \subseteq [n]$ with $|S| \geq \frac{n}{2d}$ and $u \in \mathbb{F}_p^{\overline{S}}$ such that
    \begin{align*}
        \frac{|A_{\overline{S} \rightarrow u}|}{p^{|S|}} \geq \alpha + \frac{\delta_0}{32}.
    \end{align*}

Since $n \geq \left\lceil \log_2 \alpha_0^{1-k} \right\rceil + 1$ and $\alpha \geq \alpha_0$, we have $2^{n-1} \geq \alpha^{1-k}$, that is, $\frac{\alpha}{2^n} \leq \frac{\alpha^k}{2}$. By Lemma \ref{l;large exp}, there exist an index $0 \leq j \leq k-1$ and $1$-bounded functions $f_i$, $i \neq j$, such that
    \begin{align*}
        \left| \operatorname*{\scalerel*{\mathbb{E}}{\textstyle\sum}}_{(x_0, \ldots, x_{k-1}) \sim \mu^{\otimes n}} \Big[ f_A(x_j) \prod_{\substack{i\neq j \\ 0 \leq i \leq k-1}} f_i(x_i) \Big] \right|
        \geq \frac{\alpha^k}{2^k-1} - \frac{\alpha}{2^n(2^k-1)} \geq \frac{\alpha^k}{2(2^k-1)} \geq \epsilon_0 .
    \end{align*}
    The balanced function $f_A = A - \alpha$ is $1$-bounded and $n \geq N_0$, so Theorem \ref{t;inverse} gives
    \begin{align*}
        \operatorname{Stab}_{1-\delta_0}(A - \alpha) > \delta_0 .
    \end{align*}
    By Lemma \ref{l;stability}, applied with $\delta = \delta_0$ and our choice of $d$, the balanced function is essentially of low degree:
    \begin{align*}
        W_{\leq d}(A - \alpha) \geq \frac{\delta_0}{2}.
    \end{align*}
    We now apply Lemma \ref{p;restriction} on $\Sigma = \mathbb{F}_p$ equipped with the uniform measure, which is the common marginal of $\mu$ (Lemma \ref{l;large exp}), with $\beta = \frac{\delta_0}{2}$. Its hypothesis $\beta \geq 16 \exp \left( -\frac{n}{2d^2} \right)$ is equivalent to $n \geq 2d^2 \log \frac{32}{\delta_0}$, which holds since $n \geq N(\alpha_0)$. The lemma yields $S \subseteq [n]$ with $|S| \geq \frac{n}{2d}$ and $u \in \mathbb{F}_p^{\overline{S}}$ such that the density of $A_{\overline{S} \rightarrow u}$ in $\mathbb{F}_p^S$ is at least $\alpha + \frac{\beta}{16} = \alpha + \frac{\delta_0}{32}$.

Let $A \subseteq \mathbb{F}_p^n$ contain no nontrivial restricted $k$-term polynomial progression, that is, no valid $k$-tuple, and let $\alpha_0 = \frac{|A|}{p^n} > 0$. Let $\delta_0$, $d$ and $N(\alpha_0)$ be as in \eqref{e;de0} and \eqref{e;d0N}, and let $J \coloneqq \lfloor 32/\delta_0 \rfloor$.

    \emph{The iteration.} Set $A_0 = A$ and $n_0 = n$. Suppose that $A_j \subseteq \mathbb{F}_p^{n_j}$ has been constructed, contains no valid $k$-tuple, and has density $\alpha_j \geq \alpha_0 + j \frac{\delta_0}{32}$. If $n_j \geq N(\alpha_0)$, Lemma \ref{l;increment} (which applies since $\alpha_j \geq \alpha_0$) gives $S_j \subseteq [n_j]$ with $|S_j| \geq \frac{n_j}{2d}$ and a point $u_j \in \mathbb{F}_p^{\overline{S_j}}$. We set $A_{j+1} \coloneqq (A_j)_{\overline{S_j} \rightarrow u_j} \subseteq \mathbb{F}_p^{S_j}$ and $n_{j+1} \coloneqq |S_j|$. By Lemma \ref{l;fiber}, $A_{j+1}$ contains no valid $k$-tuple, and its density satisfies $\alpha_{j+1} \geq \alpha_j + \frac{\delta_0}{32} \geq \alpha_0 + (j+1)\frac{\delta_0}{32}$.

    \emph{Termination.} Densities never exceed $1$, while $\alpha_0 + (J+1)\frac{\delta_0}{32} > 1$. Hence the procedure cannot complete $J+1$ steps, so there is some $j \leq J$ with $n_j < N(\alpha_0)$. Since $n_{i+1} \geq \frac{n_i}{2d}$ for every $i < j$,
    \begin{align}\label{e;nbound}
        n \leq (2d)^j n_j < (2d)^{\frac{32}{\delta_0}} N(\alpha_0).
    \end{align}

    \emph{Quantitative bound.} Since $\delta_0 < \frac12$, we have $d \leq \delta_0^{-2}$. We may take $C_k\geq k+2$ and the exponent $O_\mu(k)$ in \eqref{e;de0} to be at least $1$. Then \eqref{e;de0} gives $\delta_0^{-1}\geq \exp\big((\alpha_0/C_k)^{-1}\big) \geq \frac{C_k}{\alpha_0}$, while $\left\lceil \log_2 \alpha_0^{1-k} \right\rceil + 1 \leq k\log_2\frac{1}{\alpha_0}+2 \leq \frac{k+2}{\alpha_0}$. Hence $\left\lceil \log_2 \alpha_0^{1-k} \right\rceil + 1 \leq \delta_0^{-1}$. Moreover, $2d^2 \log \frac{32}{\delta_0} \leq C \delta_0^{-5}$.  Hence $N(\alpha_0) \leq C \delta_0^{-5}$, and \eqref{e;nbound} gives
    \begin{align*}
        n < C \delta_0^{-5} \left( 2 \delta_0^{-2} \right)^{\frac{32}{\delta_0}} \leq \exp \left( C \delta_0^{-2} \right) .
    \end{align*}
    Inserting \eqref{e;de0}, we have $\delta_0^{-2} = \exp \left( 2 \exp^{(K)} \left( (\alpha_0/C_k)^{-O_\mu(k)} \right) \right)$, and therefore, after absorbing constants depending only on $k$ and $p$,
    \begin{align*}
        n < \exp^{(K+2)} \left( \left( \frac{\alpha_0}{C_k} \right)^{-O_\mu(k)} \right) .
    \end{align*}
    Taking $K+2$ logarithms, which is possible once $n$ is large enough that $\log^{(K+2)} n$ is defined (for smaller $n$ the theorem holds trivially after enlarging $C$), we obtain
    \begin{align*}
        \alpha_0 \leq C_k \left( \log^{(K+2)} n \right)^{- \frac{1}{O_{\mu} (k)} } .
    \end{align*}
    Since $K + 2 = k^{O(k)}$ and $\mu$ depends only on $k$ and $p$, this is the bound claimed in Theorem \ref{main thm}.
